class Solution:
    def maximumScore(self, a: int, b: int, c: int) -> int:
        # assumed c is the max size
        # case1: a+b > c
        # => (a+b-c)//2 + c = (a+b+c)//2 < a+b
        # case2: a+b <= c
        # => a+b <= (a+b+c)//2
        return min((a+b+c)//2, a+b+c - max(a, b, c))

