class Solution:
    def minStoneSum(self, piles: List[int], k: int) -> int:
        for i, x in enumerate(piles):
            piles[i] = -x
        heapq.heapify(piles)
        for i in range(k):
            heapq.heappush(piles, heapq.heappop(piles)//2)
        return -sum(piles)

